import urllib.request
import pandas as pd
from bs4 import BeautifulSoup
import time

headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'}

urls = {
    "eng_wales": "https://en.wikipedia.org/wiki/List_of_Areas_of_Outstanding_Natural_Beauty_in_England_and_Wales",
    "ni": "https://en.wikipedia.org/wiki/Area_of_Outstanding_Natural_Beauty",
    "nsa": "https://en.wikipedia.org/wiki/National_scenic_area_(Scotland)"
}

htmls = {}
for k, url in urls.items():
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req) as response:
        htmls[k] = response.read()
    time.sleep(1)

for k, html in htmls.items():
    try:
        tables = pd.read_html(html)
        print(f"{k} tables: {len(tables)}")
        for i, t in enumerate(tables):
            if len(t) > 5:
                print(f"Table {i} in {k}: columns {list(t.columns)}")
    except Exception as e:
        print(e)
